#include "emojineer/compiler.hpp"
#include <cstdint>
#include <stdexcept>
namespace emojineer {
Chunk Compiler::compile(const ast::Program& program){
    chunk_={};
    chunk_.source_map.clear();
    declared_types_.clear();
    function_indices_.clear();
    for(const auto&s:program.statements){
        if(auto*f=dynamic_cast<const ast::FunctionDecl*>(s.get())){
            if(function_indices_.contains(f->name))throw std::runtime_error("duplicate function '"+f->name+"'");
            std::size_t idx=chunk_.functions.size();
            function_indices_[f->name]=idx;
            emojineer::FunctionInfo fi;
            fi.name = f->name;
            fi.arity = static_cast<std::uint32_t>(f->parameters.size());
            fi.local_count = fi.arity;  // Will be updated after collecting locals
            fi.parameter_names = f->parameters;
            chunk_.functions.push_back(fi);
        }
    }
    for(const auto&s:program.statements){if(!dynamic_cast<const ast::FunctionDecl*>(s.get()))compile_stmt(*s);}
    emit(OpCode::Halt,0,0);
    for(const auto&s:program.statements){if(auto*f=dynamic_cast<const ast::FunctionDecl*>(s.get()))compile_function(*f,function_indices_.at(f->name));}
    verify_bytecode(chunk_);
    return chunk_;
}
void Compiler::collect_locals(const std::vector<ast::StmtPtr>& block){for(const auto&s:block){if(auto*v=dynamic_cast<const ast::VarDecl*>(s.get())){if(locals_.contains(v->name))throw std::runtime_error("duplicate function-local variable '"+v->name+"'");auto slot=static_cast<std::int32_t>(locals_.size());locals_[v->name]=slot;local_types_[v->name]=v->declared_type;}else if(auto*i=dynamic_cast<const ast::IfStmt*>(s.get())){collect_locals(i->then_branch);collect_locals(i->else_branch);}else if(auto*w=dynamic_cast<const ast::WhileStmt*>(s.get()))collect_locals(w->body);else if(dynamic_cast<const ast::FunctionDecl*>(s.get()))throw std::runtime_error("nested functions are not supported");}}
void Compiler::compile_function(const ast::FunctionDecl& fn,std::size_t index){in_function_=true;current_function_name_=fn.name;locals_.clear();local_types_.clear();for(const auto&p:fn.parameters){if(locals_.contains(p))throw std::runtime_error("duplicate function parameter '"+p+"'");locals_[p]=static_cast<std::int32_t>(locals_.size());local_types_[p]=std::nullopt;}collect_locals(fn.body);chunk_.functions[index].entry=static_cast<std::uint32_t>(chunk_.code.size());chunk_.functions[index].local_count=static_cast<std::uint32_t>(locals_.size());// Populate local_names: all local variable names in slot order (parameters + locals)
chunk_.functions[index].local_names.resize(locals_.size());for(const auto&[name,slot]:locals_){chunk_.functions[index].local_names[static_cast<std::size_t>(slot)]=name;}compile_block(fn.body);emit(OpCode::Constant,chunk_.add_constant(false),fn.line);emit(OpCode::Return,0,fn.line);locals_.clear();local_types_.clear();in_function_=false;current_function_name_.clear();}
void Compiler::compile_block(const std::vector<ast::StmtPtr>& block){for(const auto&s:block)compile_stmt(*s);}
std::optional<std::int32_t> Compiler::local_slot(const std::string&name)const{if(!in_function_)return std::nullopt;auto it=locals_.find(name);if(it==locals_.end())return std::nullopt;return it->second;}
void Compiler::compile_stmt(const ast::Stmt& stmt){if(dynamic_cast<const ast::ModuleDecl*>(&stmt)||dynamic_cast<const ast::ImportStmt*>(&stmt)||dynamic_cast<const ast::ExportStmt*>(&stmt))throw std::runtime_error("🧩/🔗/📤 module syntax requires file-based compilation");if(const auto*v=dynamic_cast<const ast::VarDecl*>(&stmt)){compile_expr(*v->initializer);emit_type_assert(v->declared_type,v->line);if(auto slot=local_slot(v->name))emit(OpCode::StoreLocal,*slot,v->line);else{if(declared_types_.contains(v->name))throw std::runtime_error("duplicate global variable '"+v->name+"'");emit(OpCode::StoreGlobal,name_constant(v->name),v->line);declared_types_[v->name]=v->declared_type;}return;}if(const auto*a=dynamic_cast<const ast::Assignment*>(&stmt)){compile_expr(*a->value);if(auto slot=local_slot(a->name)){emit_type_assert(local_types_.at(a->name),a->line);emit(OpCode::StoreLocal,*slot,a->line);}else{auto it=declared_types_.find(a->name);if(it!=declared_types_.end())emit_type_assert(it->second,a->line);emit(OpCode::StoreGlobal,name_constant(a->name),a->line);}return;}if(const auto*p=dynamic_cast<const ast::PrintStmt*>(&stmt)){compile_expr(*p->expression);emit(OpCode::Print,0,p->line);return;}if(const auto*r=dynamic_cast<const ast::ReturnStmt*>(&stmt)){if(!in_function_)throw std::runtime_error("📦 return is only valid inside 🛠️ functions");compile_expr(*r->expression);emit(OpCode::Return,0,r->line);return;}if(dynamic_cast<const ast::FunctionDecl*>(&stmt))throw std::runtime_error("nested functions are not supported");if(const auto*f=dynamic_cast<const ast::IfStmt*>(&stmt)){compile_expr(*f->condition);std::size_t fj=chunk_.code.size();emit(OpCode::JumpIfFalse,0,f->line);compile_block(f->then_branch);if(!f->else_branch.empty()){std::size_t ej=chunk_.code.size();emit(OpCode::Jump,0,f->line);chunk_.code[fj].operand=static_cast<std::int32_t>(chunk_.code.size());compile_block(f->else_branch);chunk_.code[ej].operand=static_cast<std::int32_t>(chunk_.code.size());}else chunk_.code[fj].operand=static_cast<std::int32_t>(chunk_.code.size());return;}if(const auto*w=dynamic_cast<const ast::WhileStmt*>(&stmt)){std::size_t start=chunk_.code.size();compile_expr(*w->condition);std::size_t exit=chunk_.code.size();emit(OpCode::JumpIfFalse,0,w->line);compile_block(w->body);emit(OpCode::Jump,static_cast<std::int32_t>(start),w->line);chunk_.code[exit].operand=static_cast<std::int32_t>(chunk_.code.size());return;}throw std::runtime_error("compiler encountered unknown statement node");}
void Compiler::compile_expr(const ast::Expr& expr){if(const auto*l=dynamic_cast<const ast::LiteralExpr*>(&expr)){std::visit([&](const auto&v){emit(OpCode::Constant,chunk_.add_constant(Value{v}),expr.line);},l->value);return;}if(const auto*v=dynamic_cast<const ast::VariableExpr*>(&expr)){if(auto slot=local_slot(v->name))emit(OpCode::LoadLocal,*slot,expr.line);else emit(OpCode::LoadGlobal,name_constant(v->name),expr.line);return;}if(dynamic_cast<const ast::InputExpr*>(&expr)){emit(OpCode::ReadLine,0,expr.line);return;}if(const auto*a=dynamic_cast<const ast::ArrayExpr*>(&expr)){if(a->elements.size()>static_cast<std::size_t>(INT32_MAX))throw std::runtime_error("array literal has too many elements");for(const auto&e:a->elements)compile_expr(*e);emit(OpCode::MakeArray,static_cast<std::int32_t>(a->elements.size()),expr.line);return;}if(const auto*i=dynamic_cast<const ast::IndexExpr*>(&expr)){compile_expr(*i->collection);compile_expr(*i->index);emit(OpCode::Index,0,expr.line);return;}if(const auto*l=dynamic_cast<const ast::LengthExpr*>(&expr)){compile_expr(*l->value);emit(OpCode::Length,0,expr.line);return;}if(const auto*a=dynamic_cast<const ast::AppendExpr*>(&expr)){compile_expr(*a->collection);compile_expr(*a->value);emit(OpCode::Append,0,expr.line);return;}if(const auto*s=dynamic_cast<const ast::SetIndexExpr*>(&expr)){compile_expr(*s->collection);compile_expr(*s->index);compile_expr(*s->value);emit(OpCode::SetIndex,0,expr.line);return;}if(const auto*c=dynamic_cast<const ast::CallExpr*>(&expr)){auto it=function_indices_.find(c->callee);if(it==function_indices_.end())throw std::runtime_error("undefined function '"+c->callee+"'");const auto&meta=chunk_.functions[it->second];if(c->arguments.size()!=meta.arity)throw std::runtime_error("function '"+c->callee+"' expects "+std::to_string(meta.arity)+" arguments, got "+std::to_string(c->arguments.size()));for(const auto&a:c->arguments)compile_expr(*a);emit(OpCode::Call,static_cast<std::int32_t>(it->second),expr.line);return;}if(const auto*u=dynamic_cast<const ast::UnaryExpr*>(&expr)){compile_expr(*u->right);if(u->op==TokenKind::Subtract)emit(OpCode::Negate,0,expr.line);else if(u->op==TokenKind::Not)emit(OpCode::Not,0,expr.line);else throw std::runtime_error("unsupported unary operator");return;}if(const auto*b=dynamic_cast<const ast::BinaryExpr*>(&expr)){compile_expr(*b->left);compile_expr(*b->right);switch(b->op){case TokenKind::Add:emit(OpCode::Add,0,expr.line);break;case TokenKind::Subtract:emit(OpCode::Subtract,0,expr.line);break;case TokenKind::Multiply:emit(OpCode::Multiply,0,expr.line);break;case TokenKind::Divide:emit(OpCode::Divide,0,expr.line);break;case TokenKind::Modulo:emit(OpCode::Modulo,0,expr.line);break;case TokenKind::Equal:emit(OpCode::Equal,0,expr.line);break;case TokenKind::Less:emit(OpCode::Less,0,expr.line);break;case TokenKind::Greater:emit(OpCode::Greater,0,expr.line);break;default:throw std::runtime_error("unsupported binary operator");}return;}throw std::runtime_error("compiler encountered unknown expression node");}
void Compiler::emit(OpCode op,std::int32_t operand,std::size_t line,std::size_t column){
    chunk_.code.push_back({op,operand,static_cast<std::uint32_t>(line)});
    // Emit source map entry for this instruction (v6 format with function context)
    // Note: end_line/end_column default to line/column for now; full range tracking would require AST changes
    chunk_.source_map.push_back({source_path_, static_cast<std::uint32_t>(line), static_cast<std::uint32_t>(column), static_cast<std::uint32_t>(line), static_cast<std::uint32_t>(column), current_function_name_});
}
std::int32_t Compiler::name_constant(const std::string&name){return chunk_.add_constant(name);}
void Compiler::emit_type_assert(std::optional<ast::DeclaredType>type,std::size_t line){if(!type)return;switch(*type){case ast::DeclaredType::Number:emit(OpCode::AssertNumber,0,line);break;case ast::DeclaredType::String:emit(OpCode::AssertString,0,line);break;case ast::DeclaredType::Bool:emit(OpCode::AssertBool,0,line);break;case ast::DeclaredType::Array:emit(OpCode::AssertArray,0,line);break;}}
}
